3.3. サーブレット・プログラム
以下は、EJBを呼び出すサーブレット・プログラムです。CtgXaのdoXATest()を呼び出して、その結
果をWebブラウザー画面に表示します。
<ejb/client/HelloClient.java>
package ejb.client;
import java.io.IOException;
import java.io.PrintWriter;
import javax.ejb.EJB;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

import ejb.server.CtgXa;
public class HelloClient extends HttpServlet {
private static final long serialVersionUID = 5385358571284268459L;
@EJB(mappedName="ejb.server.CtgXa")
private CtgXa ctgXaTest;
protected void processRequest(HttpServletRequest request, HttpServletResponse
response)
throws ServletException, IOException {
PrintWriter out = response.getWriter();
try {
String result = ctgXaTest.doXATest("TestData");
response.setContentType("text/html");
out.println("<html>");
out.println("<head>");
out.println("<title>HelloClient</title>");
out.println("</head>");
out.println("<body>");
out.println("<h1>" + result + "</h1>");
out.println("</body>");
out.println("</html>");
out.close();
} catch(Exception ex){
response.setContentType("text/plain");
ex.printStackTrace(out);
}
}
protected void doGet(HttpServletRequest request, HttpServletResponse response)
throws ServletException, IOException {
processRequest(request, response);
}
protected void doPost(HttpServletRequest request, HttpServletResponse response)
throws ServletException, IOException {
processRequest(request, response);
}
}

