hms_msg_t *msg;
session = hms_create_session(hms, 1, HMS_AUTO_ACK, 0);
if (session == NULL) { error processing }
/* durable_subscriberを作成する */
cons = hms_create_durable_subscriber(session, dest, "consumer_1", NULL,
NULL, 0);
